1602	\label{ALRtheta-2}
1603	\end{center}
1604	\end{sidewaysfigure}
1605	
1606	
1607	The nature of differential LR asymmetry from Eq.~\ref{A_LR-cos-obs} is shown in Fig.~\ref{ALRtheta-2} for $\mu^+\mu^-$ (top panel), $b\overline{b}$ (middle panel) and $t\overline{t}$ (bottom panel) using $M_{Z^\prime}=7.5$ TeV as a function of $\cos\theta$ for $\sqrt{s}=250$ GeV (except $t \overline{t}$), $500$ GeV, $1$ TeV and $3$ TeV respectively. We estimate the asymmetry parameter for the $U(1)_X$ scenario considering $x_H=-2$, $-1$, $1$ and $2$ and present them along with the SM result (solid black line). The LR asymmetry depends on $x_H$ through the interactions between the charged fermions and $Z^\prime$ as shown in Table~\ref{tabASM}. According to that, the differential LR asymmetry for $x_H=-2$ and $-1$ for the $e^-e^+ \to \mu^+ \mu^-$ process from Eq.~\ref{ALR-d-no-mf-1} can be written as 
1608	\begin{align}
1609	{\cal A}_{\rm LR}(\cos\theta)^{x_H=-2}
1610	 & \ \simeq \ \frac{(1+\cos\theta)^2
1611	 \left(|q^{e_{L} \mu_{L}}_{\rm{SM}}|^{2}-|q^{e_{R} \mu_{R}}|^{2}\right)
1612	 +(1-\cos\theta)^2
1613	 \left(|q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2}-|q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2}\right)
1614	}
1615	{(1+\cos\theta)^2
1616	 \left(|q^{e_{L} \mu_{L}}_{\rm{SM}}|^{2}+|q^{e_{R} \mu_{R}}|^{2}\right)
1617	 +(1-\cos\theta)^2
1618	 \left(|q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2}+|q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2}\right)
1619	 } \, ,   \label{ALR-d-no-mf-2a}  \\
1620	 {\cal A}_{\rm LR}(\cos\theta)^{x_H=-1}
1621	 & \ \simeq \ \frac{(1+\cos\theta)^2
1622	 \left(|q^{e_{L} \mu_{L}}|^{2}-|q^{e_{R} \mu_{R}}_{\rm{SM}}|^{2}\right)
1623	 +(1-\cos\theta)^2
1624	 \left(|q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2}-|q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2}\right)
1625	}
1626	{(1+\cos\theta)^2
1627	 \left(|q^{e_{L} \mu_{L}}|^{2}+|q^{e_{R} \mu_{R}}_{\rm{SM}}|^{2}\right)
1628	 +(1-\cos\theta)^2
1629	 \left(|q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2}+|q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2}\right)
1630	 }.
1631	 \label{ALR-d-no-mf-2} 
1632	\end{align}
1633	
1634	The results are shown in the top panels of Fig~\ref{ALRtheta-2}. 
1635	
1636	For the $b\overline{b}$ process we find the BSM contributions for different $x_H$ in the differential LR asymmetry in terms of $q^{\rm{XY}}$ following Table~\ref{tabASM}. Using Eq.~\ref{A_LR-cos-obs}, the differential LR asymmetry of this process for $x_H=-1$ and $1$ can be written as 
1637	\begin{align}
1638	{\cal A}_{\rm LR}(\cos\theta)^{x_H=-1}
1639	 & \ \simeq \ \frac{(1+\cos\theta)^2
1640	 \left(|q^{e_{L} b_{L}}|^{2}-|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}\right)
1641	 +(1-\cos\theta)^2
1642	 \left(|q^{e_{L} b_{R}}|^{2}-|q^{e_{R} b_{L}}_{\rm{SM}}|^{2}\right)
1643	}
1644	{(1+\cos\theta)^2
1645	 \left(|q^{e_{L} b_{L}}|^{2}+|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}\right)
1646	 +(1-\cos\theta)^2
1647	 \left(|q^{e_{L} b_{R}}|^{2}+|q^{e_{R} b_{L}}_{\rm{SM}}|^{2}\right)
1648	 } \, , \\
1649	 {\cal A}_{\rm LR}(\cos\theta)^{x_H=1}
1650	 & \ \simeq \ \frac{(1+\cos\theta)^2
1651	 \left(|q^{e_{L} b_{L}}|^{2}-|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}\right)
1652	 +(1-\cos\theta)^2
1653	 \left(|q^{e_{L} b_{R}}_{\rm{SM}}|^{2}-|q^{e_{R} b_{L}}|^{2}\right)
1654	}
1655	{(1+\cos\theta)^2
1656	 \left(|q^{e_{L} b_{L}}|^{2}+|q^{e_{R} b_{R}}_{\rm{SM}}|^{2}\right)
1657	 +(1-\cos\theta)^2
1658	 \left(|q^{e_{L} b_{R}}_{\rm{SM}}|^{2}+|q^{e_{R} b_{L}}|^{2}\right)
1659	 } \, . 
1660	\label{ALR-d-no-mf-3} 
1661	\end{align}
1662	
1663	The results are shown in the middle panels of Fig~\ref{ALRtheta-2}. Similarly, we study the LR asymmetry for $e^-e^+ \to t \overline{t}$ process according to Table~\ref{tabASM} and Eq.~\ref{A_LR-cos-obs} for different $x_H$. 
1664	
1665	We find that for all three final states, the size of the differential LR asymmetry increases with the increase in $\sqrt{s}$ from the SM prediction (solid black line). In the $U(1)_X$ case, it is governed by different couplings of the left and right-handed fermions with $Z^\prime$, as summarized in Table~\ref{tabASM}.
1666	
1667	
1668	
1669	
1670	The amount of deviation from the SM in the differential asymmetries can be defined as
1671	\begin{align}
1672	\Delta_{\mathcal{A}_{\rm LR}}(\cos\theta) & \ = \ 
1673	\frac{\mathcal{A}_{\rm LR}^{U(1)_X}(\cos\theta)}{\mathcal{A}_{\rm LR}^{\rm SM}(\cos\theta)}-1 \, .
1674	\label{DeltaALRcos}
1675	\end{align}
1676	We show these deviations using $M_{Z^\prime}=7.5$ TeV in Fig.~\ref{DevALRtheta-2} for $\mu^+\mu^-$ (top panel), $b \overline{b}$ (middle panel) and $t \overline{t}$ (bottom panel) as a function of $\cos\theta$. We use $\sqrt{s}=250$ GeV (except $t \overline{t}$), $500$ GeV, $1$ TeV and $3$ TeV and present the results for $x_H=-2$, $-1$, $1$ and $2$. The theoretically estimated statistical error, shown as the gray-shaded band is estimated from
1677	\begin{align}
1678	 \Delta \mathcal{A}^{\rm stat}_{\rm LR} \ = \ 
1679	
1680	
1681	
1682	
1683	
1684	 
1685	 \frac{2\sqrt{N_{\rm LR}N_{\rm RL}}}
1686	 {(N_{\rm LR}+N_{\rm RL})
1687	 \left(\sqrt{N_{\rm LR}}-\sqrt{N_{\rm RL}}\right)}
1688	{\cal A}_{\rm LR} \, , 
1689	\label{Eq:Error-A_LR-1-1}
1690	\end{align}
1691	where $N_{\rm LR}=\mathcal{L}_{\rm int} \, \sigma_{\rm LR}$ and $N_{\rm RL}=\mathcal{L}_{\rm int} \, \sigma_{\rm RL}$.
1692	
1693	From Fig.~\ref{DevALRtheta-2}, we find that the deviation in differential LR asymmetry for $e^-e^+ \to \mu^+ \mu^-$ process for $x_H=-2$ is slightly above the theoretically estimated statistical error for $\cos\theta > 0.37$; however, for $x_H=-1$ it is within the range of the statistical error. For $x_H=1$ and $2$, the deviations vary between $5\%-3\%$ and $10\%-8\%$ respectively for $-1 \leq \cos\theta \leq 1$. The deviations increase with $\sqrt{s}$. The differential LR asymmetry is negative for $x_H=2$ at $\sqrt{s}=3$ TeV which is reflected in the deviation of the differential LR asymmetry as well.
