1718	\subsection{Integrated left-right asymmetry (${\cal A}_{\rm LR}$)} 
1719	
1720	We also calculate the integrated $\mathcal{A}_{\rm{LR}}$ by integrating Eq.~\ref{ALR-d-A} over the scattering angle: 
1721	\begin{align}
1722	 \mathcal{A}_{\rm LR}
1723	 & \ = \ \frac{\sigma^{\rm LR}-\sigma^{\rm RL}}
1724	 {\sigma^{\rm LR}+ \sigma^{\rm RL}}.
1725	\label{ALRx}
1726	\end{align}
1727	In terms of the gauge couplings of the fermions, we can write Eq.~\ref{ALRx} as
1728	\bea
1729	 \mathcal{A}_{\rm LR} 
1730	 \ = \ \frac{\splitfrac{\Big( 1 + \frac{1}{3}\beta^{2} \Big) 
1731	 \Big[  \big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2} \big)
1732	 -  \big( |q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2} \big) \Big]}{
1733	 + 8 \frac{m_{f}^{2}}{s} \Big[ {\rm Re}(q^{e_{L}f_{L}} {q^{e_{L} f_{R}}}^{\ast})
1734	- {\rm Re}( q^{e_{R} f_{R}} {q^{e_{R} f_{L}}}^{\ast}) \Big]}}{\splitfrac{\Big( 1 + \frac{1}{3}\beta^{2} \Big) 
1735	 \Big[  \big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2} \big)
1736	 +  \big( |q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2} \big) \Big]}{ + 8 \frac{m_{f}^{2}}{s} \Big[ {\rm Re}(q^{e_{L}f_{L}} {q^{e_{L} f_{R}}}^{\ast})
1737	+ {\rm Re}( q^{e_{R} f_{R}} {q^{e_{R} f_{L}}}^{\ast}) \Big]}} \, .
1738	\label{Eq:A_LR-Qs}
1739	\eea
1740	In the limit $m_{f} \ll \sqrt{s}$, Eq.~\ref{Eq:A_LR-Qs} is reduced to
1741	\begin{align}
1742	 \mathcal{A}_{\rm LR}
1743	 & \ \simeq \  
1744	\frac{
1745	(|q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2})
1746	 - (|q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2})
1747	}{
1748	(|q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2})
1749	 + (|q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2})
1750	} \, .
